        int totalCards = in.nextInt();
        int totalShuffles = in.nextInt();

        NumberTheory.Mod998 mod = new NumberTheory.Mod998();
        mod.fInv(totalCards + totalShuffles);

        long phaseSum = 1;
        long currentProduct = 1;
        for (int i = 0; currentProduct != 0; i++) {
            currentProduct = mod.mult(currentProduct, totalCards - i, mod.smallInv(totalShuffles + totalCards - i));
            phaseSum = mod.add(phaseSum, currentProduct);
        }

        long finalAnswer = 0;
        for (int k = 1; k <= totalCards; k++) {
            finalAnswer = mod.add(finalAnswer, mod.mult(mod.paritySign(k + 1), mod.ncr(totalCards, k), totalShuffles + k, mod.smallInv(k), phaseSum));
        }
        out.println(finalAnswer);
