import sys

class NumberTheory:
    class Mod998:
        def __init__(self):
            self.modulus_value = 998244353

        def modulus(self):
            return self.modulus_value

        def add(self, a, b):
            sum_ = a + b
            return sum_ - self.modulus() if sum_ >= self.modulus() else sum_

        def mult(self, a, b):
            return (a * b) % self.modulus()

        def fact(self, n):
            while len(self.factorials) <= n:
                self.factorials.append(self.mult(self.factorials[-1], len(self.factorials)))
            return self.factorials[n]

        def fInv(self, n):
            lastIdx = len(self.invFactorials) - 1
            if lastIdx < n:
                invs = [0] * (n - lastIdx)
                invs[0] = self.inv(self.fact(n))
                for i in range(1, len(invs)):
                    invs[i] = self.mult(invs[i - 1], n - i + 1)
                for i in reversed(range(len(invs))):
                    self.invFactorials.append(invs[i])
            return self.invFactorials[n]

        def paritySign(self, k):
            return 1 if (k & 1) == 0 else self.modulus() - 1

        def ncr(self, n, r):
            if n < 0 or r < 0 or n < r:
                return 0
            return self.mult(self.fact(n), self.mult(self.fInv(r), self.fInv(n - r)))

        def smallInv(self, n):
            return self.mult(self.fInv(n), self.fact(n - 1))

        def inv(self, a):
            # Fermat's little theorem for modular inverse
            return pow(a, self.modulus() - 2, self.modulus())

        def __init__(self):
            self.factorials = [1]
            self.invFactorials = [1]

def performCalculation():
    input_data = sys.stdin.read().strip().split()
    totalCards = int(input_data[0])
    totalShuffles = int(input_data[1])

    mod = NumberTheory.Mod998()
    mod.fInv(totalCards + totalShuffles)

    phaseSum = 1
    currentProduct = 1
    i = 0
    while currentProduct != 0:
        currentProduct = mod.mult(currentProduct, totalCards - i)
        currentProduct = mod.mult(currentProduct, mod.fInv(totalShuffles + totalCards - i))
        phaseSum = mod.add(phaseSum, currentProduct)
        i += 1

    finalAnswer = 0
    for k in range(1, totalCards + 1):
        term = mod.paritySign(k + 1)
        term = mod.mult(term, mod.ncr(totalCards, k))
        term = mod.mult(term, totalShuffles + k)
        term = mod.mult(term, mod.smallInv(k))
        term = mod.mult(term, phaseSum)
        finalAnswer = mod.add(finalAnswer, term)

    print(finalAnswer)

